window.QUESTIONS=[
{id:'q01',topic:'conductismo',modes:['learn','exam'],page:4,source:'apuntes',prompt:'¿Cuál es el objetivo de la psicología conductista según los apuntes?',variants:['Para el conductismo, la psicología debe principalmente…'],options:[['Describir, predecir y controlar la conducta humana',true,'Es la formulación recogida en el temario.'],['Interpretar únicamente experiencias subjetivas',false,'El conductismo prioriza fenómenos observables y medibles.'],['Estudiar la conciencia mediante introspección',false,'Los apuntes indican que rechaza la introspección.']]},
{id:'q02',topic:'conductismo',modes:['learn','compare','exam'],page:5,source:'apuntes',prompt:'En el experimento del pequeño Albert, ¿qué era inicialmente la rata?',options:[['Un estímulo neutro',true,'Antes de asociarse al ruido no provocaba la respuesta de miedo.'],['Un estímulo incondicionado',false,'El estímulo incondicionado era el ruido fuerte.'],['Una respuesta condicionada',false,'La rata es un estímulo, no una respuesta.']]},
{id:'q03',topic:'conductismo',modes:['compare','apply','exam'],page:8,source:'apuntes',prompt:'En Pavlov, ¿qué elemento es la respuesta incondicionada?',options:[['La salivación ante la comida',true,'Ocurre de forma natural, sin aprendizaje previo.'],['La campana antes del aprendizaje',false,'Antes del aprendizaje la campana es un estímulo neutro.'],['La salivación ante la campana',false,'Esa es la respuesta condicionada, porque depende de la asociación aprendida.']]},
{id:'q04',topic:'conductismo',modes:['compare','exam'],page:10,source:'apuntes',prompt:'¿Qué principio explica responder de modo parecido ante estímulos semejantes al condicionado?',options:[['Generalización',true,'La respuesta se extiende a estímulos parecidos.'],['Discriminación',false,'La discriminación consiste en aprender a distinguir estímulos.'],['Extinción',false,'La extinción es el debilitamiento de la respuesta condicionada.']]},
{id:'q05',topic:'conductismo',modes:['apply','exam'],page:10,source:'apuntes',prompt:'Una marca deja de provocar la emoción aprendida tras mucho tiempo sin reforzar la asociación. ¿Qué proceso describe?',options:[['Extinción',true,'La respuesta aprendida se debilita al dejar de mantenerse la asociación.'],['Generalización',false,'No se está extendiendo la respuesta a estímulos similares.'],['Condicionamiento de orden superior',false,'No se está usando un estímulo ya condicionado para condicionar otro.']]},
{id:'q06',topic:'conductismo',modes:['apply','exam'],page:12,source:'apuntes',prompt:'Una colaboración une una marca ya asociada al lujo con otra ligada a la tecnología. ¿Qué concepto aparece en los apuntes?',options:[['Cobranding',true,'Se combinan dos marcas y sus asociaciones previas.'],['Extinción',false,'No se está debilitando ninguna asociación.'],['Castigo negativo',false,'No se retira un estímulo para reducir una conducta.']]},
{id:'q07',topic:'conductismo',modes:['compare','exam'],page:13,source:'apuntes',prompt:'¿Qué ley de Thorndike sostiene que las conductas con consecuencias satisfactorias tienden a repetirse?',options:[['Ley del efecto',true,'Relaciona satisfacción con fortalecimiento de la conexión.'],['Ley de cierre',false,'Es una ley perceptiva de la Gestalt.'],['Ley de semejanza',false,'También pertenece a la Gestalt.']]},
{id:'q08',topic:'conductismo',modes:['compare','apply','exam'],page:14,source:'apuntes',prompt:'Una máquina tragaperras entrega premios tras un número impredecible de jugadas. ¿Qué programa representa?',options:[['Razón variable',true,'El refuerzo depende de un número cambiante de respuestas.'],['Razón fija',false,'En razón fija el número de respuestas es predecible.'],['Intervalo fijo',false,'Aquí la condición se basa en respuestas, no en el paso de un tiempo fijo.']]},
{id:'q09',topic:'social',modes:['learn','exam'],page:17,source:'apuntes',prompt:'¿Quiénes desarrollaron la teoría de los dos pasos presentada en 1955?',options:[['Paul Lazarsfeld y Elihu Katz',true,'Son los autores indicados en el temario.'],['Petty y Cacioppo',false,'Ellos se asocian al modelo de elaboración probable.'],['Piaget y Bandura',false,'Se vinculan con aprendizaje significativo y aprendizaje social.']]},
{id:'q10',topic:'social',modes:['compare','apply','exam'],page:19,source:'apuntes',prompt:'Una campaña presenta a una marca pequeña que lucha contra líderes dominantes. ¿Qué estrategia utiliza?',options:[['Underdog',true,'Presenta al perdedor que lucha contra una posición desfavorable.'],['Bandwagon',false,'Bandwagon apela a sumarse a lo que hace la mayoría.'],['Ruta central',false,'Es una vía de persuasión basada en elaboración y argumentos.']]},
{id:'q11',topic:'social',modes:['learn','apply','exam'],page:19,source:'apuntes',prompt:'¿Qué analiza el efecto Pigmalión?',options:[['Cómo las expectativas y creencias influyen en profecías autocumplidas',true,'Las expectativas pueden modificar el trato y contribuir al resultado esperado.'],['La aceptación de descripciones vagas como personales',false,'Eso corresponde al efecto Forer o Barnum.'],['La búsqueda de datos que confirman una creencia',false,'Eso es sesgo confirmatorio.']]},
{id:'q12',topic:'social',modes:['learn','exam'],page:21,source:'apuntes',prompt:'¿Qué autor se asocia con la teoría del aprendizaje social u observacional?',options:[['Albert Bandura',true,'Bandura integra observación, modelado y factores cognitivos.'],['B. F. Skinner',false,'Skinner es central en el condicionamiento operante.'],['Iván Pavlov',false,'Pavlov se asocia al condicionamiento clásico.']]},
{id:'q13',topic:'social',modes:['apply','exam'],page:23,source:'apuntes',prompt:'Un grupo mantiene una norma aunque ninguno de sus miembros conoce ya su causa original. ¿Qué ejemplo del temario ilustra?',options:[['El efecto del quinto mono',true,'Describe la perpetuación grupal de una norma cuyo origen se ha perdido.'],['El efecto McGurk',false,'Es una integración audiovisual en la percepción del habla.'],['El efecto Forer',false,'Es aceptar descripciones generales como si fueran personales.']]},
{id:'q14',topic:'social',modes:['compare','exam'],page:24,source:'apuntes',prompt:'¿Cuáles son estrategias del aprendizaje vicario según el criterio mostrado por la profesora?',options:[['Modelado, facilitación e inhibición',true,'Es la respuesta oficial visible en la captura.'],['Discriminación, extinción y generalización',false,'Son procesos del condicionamiento clásico.'],['Modelado, facilitación e instrucción',false,'La captura marca esta combinación como incorrecta.']],official:true},
{id:'q15',topic:'cognitiva',modes:['learn','exam'],page:25,source:'apuntes',prompt:'¿Qué aportación fue crucial para los postulados del paradigma cognitivo según la pregunta oficial?',options:[['La máquina de Turing',true,'Es la respuesta oficial visible.'],['La cibernética de Skinner',false,'La opción mezcla una disciplina con un autor conductista.'],['La teoría de la información de Thorndike',false,'Thorndike se vincula al aprendizaje instrumental.']],official:true},
{id:'q16',topic:'cognitiva',modes:['compare','exam'],page:27,source:'apuntes',prompt:'En Piaget, ¿qué diferencia la acomodación de la asimilación?',options:[['La acomodación reorganiza esquemas cuando lo nuevo no encaja',true,'Implica modificar la estructura cognitiva previa.'],['La acomodación incorpora lo nuevo sin cambiar esquemas',false,'Eso describe mejor la asimilación.'],['La acomodación elimina la información contradictoria',false,'No consiste en ignorar lo nuevo, sino en ajustar los esquemas.']]},
{id:'q17',topic:'cognitiva',modes:['learn','exam'],page:26,source:'oficial',prompt:'¿Qué es la asimilación en el aprendizaje significativo según la respuesta oficial?',options:[['Percepción del estímulo externo en base a su estructura cognitiva',true,'Es la respuesta oficial visible en la captura.'],['Coherencia interna de organización',false,'La captura la marca como incorrecta.'],['Regulación de procesos cognitivos',false,'No es la opción oficial mostrada.']],official:true},
{id:'q18',topic:'cognitiva',modes:['compare','apply','exam'],page:28,source:'apuntes',prompt:'En el modelo de elaboración probable, una decisión guiada por atractivo o familiaridad sigue principalmente…',options:[['El procesamiento periférico',true,'Se apoya en claves externas y poca elaboración del argumento.'],['El procesamiento central',false,'Exige motivación y análisis más cuidadoso de argumentos.'],['El condicionamiento instrumental',false,'Es un modelo de aprendizaje por consecuencias.']]},
{id:'q19',topic:'cognitiva',modes:['apply','exam'],page:30,source:'apuntes',prompt:'Percibir una figura completa aunque falten partes corresponde a la ley Gestalt de…',options:[['Cierre',true,'La mente completa configuraciones incompletas.'],['Proximidad',false,'Agrupa elementos cercanos entre sí.'],['Semejanza',false,'Agrupa elementos con características parecidas.']]},
{id:'q20',topic:'neuro',modes:['learn','compare','exam'],page:34,source:'apuntes',prompt:'¿Qué sistema de procesamiento es rápido, automático y requiere poco esfuerzo?',options:[['Sistema 1',true,'Opera de forma rápida, intuitiva y automática.'],['Sistema 2',false,'Es más lento, deliberado y exige esfuerzo.'],['Memoria episódica',false,'Es un sistema de memoria, no uno de los dos modos de procesamiento descritos.']]},
{id:'q21',topic:'neuro',modes:['learn','exam'],page:34,source:'oficial',prompt:'Los sesgos son…',options:[['Respuestas erróneas derivadas de una desviación sistemática de la racionalidad',true,'Es la definición marcada como correcta por la profesora; el PDF los presenta como desviaciones sistemáticas en la forma de razonar o interpretar la realidad.'],['Variables contextuales que perjudican la economía cognitiva',false,'No es la respuesta oficial mostrada.'],['Conductas resultantes de un condicionamiento clásico superior',false,'Confunde sesgos cognitivos con aprendizaje asociativo.']],official:true},
{id:'q22',topic:'neuro',modes:['compare','exam'],page:36,source:'apuntes',prompt:'Aceptar una descripción general como si retratara exactamente tu personalidad es…',options:[['Efecto Forer o Barnum',true,'Es la falacia de validación personal descrita en el temario.'],['Efecto Pigmalión',false,'Este se relaciona con expectativas y profecías autocumplidas.'],['Priming',false,'El priming describe la influencia de estímulos previos en el procesamiento posterior.']]},
{id:'q23',topic:'neuro',modes:['learn','exam'],page:38,source:'apuntes',prompt:'El caso de Phineas Gage ayudó a relacionar los lóbulos frontales con…',options:[['Emoción, planificación y comportamiento social',true,'Es la relación destacada en los apuntes.'],['La percepción exclusiva del color',false,'La visión del color no es la conclusión central del caso.'],['El reflejo condicionado',false,'Ese concepto pertenece al condicionamiento clásico.']]},
{id:'q24',topic:'neuro',modes:['learn','exam'],page:38,source:'oficial',prompt:'El marcador somático es, según la respuesta oficial del examen…',options:[['Un sentimiento creado a partir de una emoción',true,'Es la formulación que la profesora marcó como correcta; el PDF define los marcadores somáticos como un caso especial de sentimientos generados a partir de emociones secundarias.'],['Un proceso del soma prefrontal que mantiene la atención focalizada',false,'La captura marca esta alternativa como incorrecta.'],['Un patrón que inhibe conexiones sinápticas en la atención',false,'No es la respuesta oficial.']],official:true,note:'Criterio de profesora: formulación simplificada. El PDF desarrolla el matiz en el apartado de Damasio.'},
{id:'q25',topic:'neuro',modes:['compare','exam'],page:41,source:'oficial',prompt:'¿Cuál es la respuesta neuronal más rápida según la pregunta oficial?',options:[['Atención implícita',true,'Es la alternativa marcada como correcta; el PDF indica que la atención automática o implícita sigue el camino corto y tarda aproximadamente 125 milisegundos.'],['Atención explícita',false,'Requiere procesamiento consciente y corresponde al sistema controlado.'],['Procesos conscientes',false,'Son más lentos que la respuesta implícita.']],official:true},
{id:'q26',topic:'neuro',modes:['learn','exam'],page:44,source:'oficial',prompt:'¿Con qué mecanismo o estructura neurológica se asocia el aprendizaje vicario?',options:[['El funcionamiento de las neuronas espejo',true,'Es la respuesta oficial visible en la captura; el PDF explica que se activan al ejecutar y al observar una acción.'],['El aprendizaje activo',false,'La captura marca esta opción como incorrecta; es un tipo de participación, no una estructura neurológica.'],['El procesamiento de sesgos',false,'No es el mecanismo indicado.']],official:true},
{id:'q27',topic:'neuro',modes:['apply','exam'],page:49,source:'apuntes',prompt:'Al ver hablar a alguien, la imagen de sus labios cambia el sonido que crees oír. ¿Qué fenómeno es?',options:[['Efecto McGurk',true,'La información visual modifica la percepción auditiva del habla.'],['Priming semántico',false,'No describe una integración audiovisual simultánea.'],['Ley del efecto',false,'Es una ley del aprendizaje instrumental.']]},
{id:'q28',topic:'neuromarketing',modes:['learn','exam'],page:51,source:'oficial',prompt:'Ante la crisis del “Reto Pepsi”, Coca-Cola decidió…',options:[['Crear un nuevo producto modificando la fórmula de Coca-Cola',true,'Es la respuesta oficial visible en la captura; el PDF indica que Coca-Cola decidió cambiar su fórmula.'],['Aumentar su nicho con un nuevo target',false,'No es la decisión indicada por la profesora ni por el PDF.'],['Crear exclusivamente botellas de dos litros',false,'La captura no identifica esta opción como correcta y el PDF no atribuye la respuesta a un cambio de formato.']],official:true},
{id:'q29',topic:'neuromarketing',modes:['learn','exam'],page:52,source:'apuntes',prompt:'En el estudio neuromarketing de Coca-Cola y Pepsi, ¿cuántos participantes se citan?',options:[['67',true,'Es el total indicado en los apuntes.'],['25',false,'No es el tamaño de muestra señalado.'],['120',false,'No coincide con el dato del temario.']]},
{id:'q30',topic:'neuromarketing',modes:['compare','exam'],page:54,source:'apuntes',prompt:'¿Qué técnica registra la actividad eléctrica producida por las contracciones del corazón?',options:[['Electrocardiografía (ECG o EKG)',true,'Mide la actividad eléctrica cardíaca mediante electrodos.'],['Electroencefalografía (EEG)',false,'Registra actividad eléctrica cerebral, no cardíaca.'],['Eye tracker',false,'Registra posición y patrones de movimiento ocular.']]},
{id:'q31',topic:'neuromarketing',modes:['apply','exam'],page:57,source:'apuntes',prompt:'Para comprobar qué zonas de un anuncio reciben más atención visual se usaría principalmente…',options:[['Eye tracker y mapas de calor',true,'Permiten seguir la mirada y representar puntos de atención.'],['FACS',false,'FACS codifica movimientos y expresiones faciales.'],['Electrocardiograma',false,'Mide actividad cardíaca, no localiza la mirada.']]},
{id:'q32',topic:'neuromarketing',modes:['compare','exam'],page:58,source:'apuntes',prompt:'La respuesta galvánica de la piel informa sobre todo de…',options:[['La intensidad de la activación emocional y el nivel de atención',true,'La conductancia cambia con la activación de las glándulas sudoríparas; el PDF señala que mide intensidad y atención.'],['La valencia exacta de la emoción',false,'Por sí sola no distingue si la emoción es positiva o negativa.'],['La dirección precisa de la mirada',false,'Eso corresponde al seguimiento ocular.']]},
{id:'q33',topic:'conductismo',modes:['learn','exam'],page:7,source:'apuntes',prompt:'Para Rogers, un mensaje de miedo eficaz debe acompañarse especialmente de…',options:[['Una solución clara que refuerce la autoeficacia',true,'El receptor debe percibir que puede actuar para evitar el daño.'],['Una amenaza extrema sin instrucciones',false,'Puede provocar indefensión aprendida o evitación.'],['Repetición ilimitada del estímulo amenazante',false,'El exceso puede favorecer desensibilización.']]},
{id:'q34',topic:'social',modes:['compare','exam'],page:18,source:'apuntes',prompt:'¿Qué dimensión de la identidad social contiene juicios sobre el propio grupo y otros grupos?',options:[['Evaluativa',true,'Incluye valoraciones y juicios.'],['Cognitiva',false,'Se refiere a lo que sabemos o creemos sobre el grupo.'],['Operante',false,'No es una dimensión de identidad social.']]},
{id:'q35',topic:'neuro',modes:['compare','exam'],page:35,source:'apuntes',prompt:'Buscar y valorar sobre todo datos que apoyan una creencia previa es…',options:[['Sesgo confirmatorio',true,'También se menciona como cherry picking; consiste en atender a la información que confirma las propias creencias.'],['Efecto Forer',false,'Describe la aceptación de afirmaciones vagas como si fueran personales.'],['Discriminación estimular',false,'Es un proceso de aprendizaje, no un sesgo de selección de evidencia.']]},
{id:'q36',topic:'conductismo',modes:['learn','exam'],page:8,source:'oficial',prompt:'¿En qué condicionamiento se utiliza el concepto “reflejo condicionado”?',options:[['Condicionamiento clásico',true,'Es la respuesta oficial visible en la captura; el PDF describe el reflejo condicionado dentro del experimento clásico de Pavlov.'],['Condicionamiento instrumental',false,'Se centra en una conducta activa y sus consecuencias.'],['Condicionamiento operante',false,'Se relaciona con refuerzos, castigos y programas de reforzamiento.']],official:true},
{id:'q37',topic:'conductismo',modes:['learn','exam'],page:8,source:'oficial',prompt:'En el experimento de Pavlov, el reflejo condicionado era…',options:[['La salivación ante el sonido de la campanilla',true,'Es la respuesta oficial y requiere mencionar el estímulo aprendido.'],['La salivación',false,'Es incompleta: también existe salivación natural ante la comida.'],['La comida contigua a la campanilla',false,'Describe estímulos, no el reflejo o respuesta.']],official:true},
{id:'q38',topic:'conductismo',kind:'author',modes:['learn','compare','exam'],page:3,source:'apuntes',prompt:'¿A qué autor presentan los apuntes como precursor del conductismo y asociado a la relación entre mente y cuerpo?',options:[['William James',true,'Los apuntes lo identifican como precursor del conductismo y recogen su idea de que toda modificación conlleva un cambio corporal.'],['Wilhelm Wundt',false,'Wundt aparece como fundador de la psicología científica y de laboratorio, no con esa formulación.'],['John B. Watson',false,'Watson aparece como padre y figura central del conductismo, no como el precursor citado.']]},
{id:'q39',topic:'conductismo',kind:'author',modes:['learn','compare','exam'],page:3,source:'apuntes',prompt:'¿Quién figura como fundador de la psicología científica y de la psicología de laboratorio?',options:[['Wilhelm Wundt',true,'Es la atribución exacta que aparece en la página 3.'],['William James',false,'James se presenta como precursor del conductismo.'],['B. F. Skinner',false,'Skinner desarrolló el aprendizaje operante.']]},
{id:'q40',topic:'conductismo',kind:'author',modes:['learn','compare','exam'],page:4,source:'apuntes',prompt:'¿Qué doble condición atribuyen los apuntes a John B. Watson?',options:[['Padre del conductismo y de la investigación de mercado',true,'El PDF le atribuye expresamente ambas condiciones.'],['Fundador de la psicología de laboratorio y de la Gestalt',false,'La psicología de laboratorio se atribuye a Wundt y la Gestalt es otro enfoque.'],['Creador del aprendizaje operante y de la caja problema',false,'El aprendizaje operante se asocia a Skinner y la caja problema a Thorndike.']]},
{id:'q41',topic:'conductismo',kind:'author',modes:['learn','exam'],page:6,source:'apuntes',prompt:'¿Qué agencia contrató a Watson por sus conocimientos sobre conductismo?',options:[['Walter Thompson',true,'Es la agencia nombrada en los apuntes.'],['Future Minds Lab',false,'Es el laboratorio relacionado con el experimento de decisiones inconscientes.'],['Universidad de Stanford',false,'Es el contexto del experimento de Zimbardo, no una agencia publicitaria.']]},
{id:'q42',topic:'conductismo',kind:'author',modes:['compare','apply','exam'],page:6,source:'apuntes',prompt:'Una campaña de miedo es eficaz en un nivel moderado, pero pierde eficacia cuando la amenaza es excesiva. ¿Qué autor y qué forma explican este patrón?',options:[['McGuire; una V invertida',true,'McGuire (1969) propuso una relación en V invertida entre miedo y efectividad.'],['Rogers; una relación lineal creciente',false,'Rogers destacó la solución y la autoeficacia; no formuló esa relación lineal.'],['Bandura; una curva de aprendizaje vicario',false,'Bandura estudió aprendizaje por observación, no esta relación miedo-eficacia.']]},
{id:'q43',topic:'conductismo',kind:'compare',modes:['compare','apply','exam'],page:7,source:'apuntes',prompt:'¿Qué distingue la propuesta de Rogers sobre mensajes de miedo?',options:[['La amenaza debe ir acompañada de una solución clara que refuerce la autoeficacia',true,'Rogers advierte de la indefensión si se presenta miedo sin mostrar una acción posible.'],['Cuanto más extremo sea el miedo, mayor será siempre la persuasión',false,'Los apuntes explican que el exceso puede provocar rechazo, evitación o indefensión.'],['La amenaza funciona aunque el receptor no pueda actuar',false,'Precisamente debe percibir que puede actuar para evitar el daño.']]},
{id:'q44',topic:'conductismo',kind:'experiment',modes:['learn','compare','exam'],page:7,source:'apuntes',prompt:'¿Qué asociación autor–experimento–corriente es correcta?',options:[['Pavlov — perros y campana — condicionamiento clásico',true,'Pavlov asoció repetidamente campana y comida hasta provocar salivación ante la campana.'],['Thorndike — perros y campana — aprendizaje operante',false,'Thorndike trabajó con un gato en una caja y aprendizaje instrumental.'],['Skinner — muñeco Bobo — aprendizaje social',false,'El muñeco Bobo corresponde a Bandura.']]},
{id:'q45',topic:'conductismo',kind:'experiment',modes:['learn','compare','exam'],page:12,source:'apuntes',prompt:'¿Quién realizó la “trampa de caja”, con qué animal y dentro de qué aprendizaje?',options:[['Thorndike; un gato; aprendizaje instrumental',true,'El gato debía descubrir por ensayo y error cómo accionar el peldaño para escapar.'],['Skinner; una paloma; condicionamiento clásico',false,'Skinner estudió aprendizaje operante y la caja descrita usa un ratón; las palomas aparecen en programas de refuerzo.'],['Pavlov; un perro; aprendizaje vicario',false,'Pavlov estudió condicionamiento clásico, no aprendizaje vicario.']]},
{id:'q46',topic:'conductismo',kind:'compare',modes:['compare','exam'],page:12,source:'apuntes',prompt:'¿Qué diferencia subrayan los apuntes entre el gato de Thorndike y el perro de Pavlov?',options:[['El gato actúa para obtener una consecuencia; el perro responde de forma pasiva',true,'Thorndike plantea un sujeto activo por ensayo-error, frente a la respuesta refleja de Pavlov.'],['El perro decide qué estímulo recibir y el gato solo saliva',false,'Invierte los papeles descritos en el PDF.'],['Ambos aprenden exclusivamente por observación de un modelo',false,'Eso corresponde al aprendizaje social de Bandura.']]},
{id:'q47',topic:'conductismo',kind:'compare',modes:['compare','apply','exam'],page:13,source:'apuntes',prompt:'¿Qué ley de Thorndike expresa “mayor conexión es igual a mayor práctica”?',options:[['Ley del ejercicio',true,'La repetición fortalece la conexión entre estímulo y respuesta.'],['Ley del efecto',false,'La ley del efecto relaciona la satisfacción de la consecuencia con la repetición.'],['Ley de frecuencia',false,'En los apuntes aparece dentro del aprendizaje operante de Skinner.']]},
{id:'q48',topic:'conductismo',kind:'experiment',modes:['learn','compare','exam'],page:13,source:'apuntes',prompt:'En la caja de Skinner descrita en los apuntes, ¿qué aprende a hacer el ratón?',options:[['Presionar una palanca para obtener comida o evitar una descarga',true,'La caja estudia cómo las consecuencias refuerzan o castigan una conducta activa.'],['Salivar al oír una campana',false,'Es el reflejo condicionado del experimento de Pavlov.'],['Imitar la agresión de un adulto a un muñeco',false,'Es el experimento del muñeco Bobo de Bandura.']]},
{id:'q49',topic:'conductismo',kind:'apply',modes:['apply','exam'],page:14,source:'apuntes',prompt:'En la caja de Skinner, la luz verde que indica que pulsar la palanca sí dará comida funciona como…',options:[['Estímulo discriminativo',true,'Señala cuándo una respuesta concreta será reforzada.'],['Estímulo incondicionado',false,'No provoca una respuesta natural automática como la comida en Pavlov.'],['Respuesta condicionada',false,'Es una señal antecedente, no una respuesta del animal.']]},
{id:'q50',topic:'social',kind:'author',modes:['learn','compare','exam'],page:15,source:'apuntes',prompt:'¿Qué autor impulsó la psicología social mediante la teoría de campo?',options:[['Kurt Lewin',true,'La página 15 atribuye a Lewin la teoría de campo.'],['Henri Tajfel',false,'Tajfel desarrolló la teoría de la identidad social.'],['Elihu Katz',false,'Katz, junto a Lazarsfeld, desarrolló la teoría de los dos pasos.']]},
{id:'q51',topic:'social',kind:'apply',modes:['apply','exam'],page:17,source:'apuntes',prompt:'Un medio influye primero en una persona experta y creíble, que después interpreta el mensaje para su grupo. ¿Qué teoría y autores encajan?',options:[['Teoría de los dos pasos; Lazarsfeld y Katz',true,'El líder de opinión filtra y transmite el mensaje a su grupo de referencia.'],['Teoría de campo; Lewin y Tajfel',false,'La teoría de campo analiza persona y ambiente, no esta cadena de influencia mediática.'],['Modelo de elaboración; Petty y Cacioppo',false,'Explica rutas de procesamiento persuasivo, no los dos escalones de difusión.']]},
{id:'q52',topic:'social',kind:'author',modes:['learn','compare','exam'],page:17,source:'apuntes',prompt:'¿Quién desarrolló la teoría de la identidad social?',options:[['Henri Tajfel',true,'Los apuntes atribuyen esta teoría a Henri Tajfel.'],['Kurt Lewin',false,'Lewin se asocia a la teoría de campo.'],['Robert Rosenthal',false,'Rosenthal y Jacobson estudiaron el efecto Pigmalión.']]},
{id:'q53',topic:'social',kind:'author',modes:['learn','compare','exam'],page:19,source:'apuntes',prompt:'¿Qué pareja de investigadores se vincula al efecto Pigmalión o profecía autocumplida?',options:[['Rosenthal y Jacobson',true,'Los apuntes sitúan su estudio en la década de 1960.'],['Lazarsfeld y Katz',false,'Son los autores de la teoría de los dos pasos.'],['Petty y Cacioppo',false,'Son los autores del modelo de elaboración probable.']]},
{id:'q54',topic:'social',kind:'experiment',modes:['learn','apply','exam'],page:20,source:'apuntes',prompt:'¿Qué experimento usó una cárcel simulada y roles aleatorios de guardianes y prisioneros?',options:[['La prisión de Stanford, de Philip Zimbardo',true,'El experimento buscó mostrar cómo la situación y los roles podían modificar la conducta.'],['El muñeco Bobo, de Albert Bandura',false,'Ese estudio expuso a niños a modelos adultos agresivos o tranquilos.'],['La caja problema, de Edward Thorndike',false,'Ese experimento estudió ensayo-error con un gato.']]},
{id:'q55',topic:'social',kind:'experiment',modes:['learn','compare','exam'],page:21,source:'apuntes',prompt:'¿Qué mostró el experimento del muñeco Bobo de Bandura según los apuntes?',options:[['Que los niños tendían a imitar el comportamiento agresivo o tranquilo observado en adultos',true,'El resultado apoya el aprendizaje por observación e imitación de modelos.'],['Que una respuesta refleja puede condicionarse con una campana',false,'Ese hallazgo corresponde a Pavlov.'],['Que los roles carcelarios alteran permanentemente la personalidad',false,'El PDF indica que el efecto de Stanford fue contextual, no permanente.']]},
{id:'q56',topic:'social',kind:'hard',modes:['compare','exam'],page:22,source:'apuntes',prompt:'¿Qué precisión es imprescindible sobre el “efecto del quinto mono” en estos apuntes?',options:[['Se presenta como un experimento ficticio o metáfora',true,'El PDF lo llama explícitamente experimento ficticio y lo usa para ilustrar la perpetuación de normas.'],['Fue un ensayo controlado realizado por Bandura',false,'No se atribuye a Bandura y el texto niega que sea un experimento real.'],['Demostró causalmente el castigo vicario en primates',false,'Esa formulación convertiría una metáfora en evidencia experimental que el PDF no ofrece.']]},
{id:'q57',topic:'social',kind:'compare',modes:['compare','exam'],page:23,source:'apuntes',prompt:'¿Cuál es la secuencia completa de requisitos del aprendizaje observacional de Bandura?',options:[['Atención, retención, reproducción motora y motivación',true,'Son los cuatro procesos enumerados en las páginas 23 y 24.'],['Asimilación, acomodación, equilibración y refuerzo',false,'Los tres primeros son procesos de Piaget y el último pertenece al aprendizaje por consecuencias.'],['Percepción, emoción, conación y extinción',false,'Mezcla fases y conceptos de marcos distintos.']]},
{id:'q58',topic:'cognitiva',kind:'author',modes:['learn','compare','exam'],page:25,source:'apuntes',prompt:'¿Qué pareja aparece como precursora de la psicología cognitiva?',options:[['Jean Piaget y Donald Broadbent',true,'Es la pareja citada al inicio del bloque cognitivo.'],['William James y Wilhelm Wundt',false,'Aparecen en la introducción histórica del conductismo.'],['Kahneman y Herbert Simon',false,'Se vinculan a decisiones y racionalidad restringida.']]},
{id:'q59',topic:'cognitiva',kind:'compare',modes:['compare','exam'],page:25,source:'apuntes',prompt:'¿Qué correspondencia entre desarrollo y autor es correcta en el origen de la psicología cognitiva?',options:[['Máquina de Turing — Turing; teoría de la información — Shannon; cibernética — Wiener',true,'Las tres influencias aparecen asociadas así en el PDF.'],['Máquina de Turing — Wiener; teoría de la información — Piaget; cibernética — Shannon',false,'Desplaza e intercambia las atribuciones del temario.'],['Máquina de Turing — Watson; teoría de la información — Skinner; cibernética — Pavlov',false,'Son autores del bloque conductista, no de esos desarrollos.']]},
{id:'q60',topic:'cognitiva',kind:'apply',modes:['apply','compare','exam'],page:27,source:'apuntes',prompt:'Una información nueva no encaja; la persona modifica sus esquemas y después recupera la coherencia. ¿Qué dos procesos aparecen, por orden?',options:[['Acomodación y equilibración',true,'Primero se reorganizan los esquemas; después la autorregulación restablece el equilibrio.'],['Asimilación y generalización',false,'La asimilación interpreta desde esquemas previos y la generalización pertenece al condicionamiento.'],['Retención y reproducción motora',false,'Son requisitos del aprendizaje observacional de Bandura.']]},
{id:'q61',topic:'cognitiva',kind:'author',modes:['learn','compare','exam'],page:27,source:'apuntes',prompt:'¿Qué autores propusieron el modelo de jerarquía de los efectos y cuál es su orden?',options:[['Lavidge y Steiner; cognitivo, afectivo, conativo',true,'El modelo avanza desde información y atención, pasa por valoración emocional y culmina en acción.'],['Petty y Cacioppo; afectivo, cognitivo, conativo',false,'Petty y Cacioppo desarrollaron el modelo de elaboración probable.'],['Piaget y Broadbent; conativo, afectivo, cognitivo',false,'No son los autores de esta jerarquía y el orden está invertido.']]},
{id:'q62',topic:'cognitiva',kind:'author',modes:['learn','compare','exam'],page:28,source:'apuntes',prompt:'¿Quiénes desarrollaron el Modelo de Elaboración Probable?',options:[['Richard E. Petty y John Cacioppo',true,'Son los dos autores nombrados en el apartado 3.5.'],['Paul Lazarsfeld y Elihu Katz',false,'Desarrollaron la teoría de los dos pasos.'],['Rosenthal y Jacobson',false,'Estudiaron el efecto Pigmalión.']]},
{id:'q63',topic:'cognitiva',kind:'compare',modes:['compare','apply','exam'],page:28,source:'apuntes',prompt:'Una persona muy implicada compara argumentos y adopta una actitud resistente al cambio. ¿Qué ruta ha seguido?',options:[['Procesamiento central',true,'La elaboración profunda e integración en esquemas produce cambios más duraderos.'],['Procesamiento periférico',false,'Se apoya en claves superficiales y poca elaboración.'],['Condicionamiento instrumental',false,'Es aprendizaje activo por consecuencias, no una ruta del ELM.']]},
{id:'q64',topic:'cognitiva',kind:'apply',modes:['apply','exam'],page:28,source:'apuntes',prompt:'Elegir por la celebridad, el envase, la música o el lugar de venta indica principalmente…',options:[['Procesamiento periférico',true,'Son claves superficiales enumeradas por el modelo de elaboración probable.'],['Procesamiento central',false,'La ruta central exige evaluación activa del corpus argumental.'],['Equilibración',false,'Es la autorregulación entre asimilación y acomodación en Piaget.']]},
{id:'q65',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:31,source:'apuntes',prompt:'¿A quién presentan los apuntes como padre de la neurociencia moderna y autor de la doctrina de la neurona?',options:[['Santiago Ramón y Cajal',true,'El PDF le atribuye la observación y tinción de neuronas y la descripción de la sinapsis.'],['Antonio Damasio',false,'Damasio propuso la hipótesis del marcador somático.'],['Joseph LeDoux',false,'Aparece en el apartado sobre emoción, no como autor de la doctrina de la neurona.']]},
{id:'q66',topic:'neuro',kind:'experiment',modes:['learn','apply','exam'],page:33,source:'apuntes',prompt:'¿Qué hallazgo atribuyen los apuntes al experimento de Roger Koenig-Robert y Joel Pearson?',options:[['Los patrones cerebrales permitían anticipar la elección hasta once segundos antes de la consciencia del participante',true,'El técnico reconocía la opción antes de que el sujeto declarara ser consciente de decidir.'],['La mirada permitía predecir la compra exactamente 125 ms antes',false,'Los 125 ms corresponden a atención automática, no a este experimento.'],['La corteza prefrontal iniciaba siempre la decisión racional',false,'El texto sugiere que puede intervenir más en la justificación posterior que en el origen.']]},
{id:'q67',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:34,source:'apuntes',prompt:'¿Qué trío relacionan los apuntes con decisiones bajo incertidumbre y racionalidad restringida?',options:[['Daniel Kahneman, Vernon Smith y Herbert Alexander Simon',true,'Son los tres nombres citados en el inicio del apartado de sistemas de procesamiento.'],['Petty, Cacioppo y Broadbent',false,'Se relacionan con persuasión y psicología cognitiva, no con ese trío.'],['James, Lange y Cannon',false,'Son autores de teorías de la emoción.']]},
{id:'q68',topic:'neuro',kind:'author',modes:['compare','exam'],page:36,source:'apuntes',prompt:'Según James y Lange, ¿qué secuencia origina la emoción?',options:[['Estímulo → respuesta fisiológica → percepción corporal → emoción',true,'La emoción surge al percibir la respuesta del propio cuerpo.'],['Estímulo → emoción y respuesta fisiológica simultáneas',false,'Esa es la propuesta de Cannon y Bard.'],['Estímulo → evaluación cognitiva → emoción',false,'Esa formulación corresponde a Lazarus.']]},
{id:'q69',topic:'neuro',kind:'author',modes:['compare','exam'],page:36,source:'apuntes',prompt:'¿Qué sostienen Cannon y Bard frente a James y Lange?',options:[['El estímulo desencadena simultáneamente emoción y respuesta fisiológica',true,'Niegan que la percepción fisiológica tenga que causar primero la emoción.'],['La emoción exige interpretar cognitivamente dos factores',false,'Esa es la teoría bifactorial de Schachter y Singer.'],['La reacción afectiva siempre precede a cualquier fisiología',false,'No es la formulación que les atribuye el PDF.']]},
{id:'q70',topic:'neuro',kind:'author',modes:['compare','apply','exam'],page:36,source:'apuntes',prompt:'Activación corporal más interpretación cognitiva del contexto: ¿qué teoría y autores?',options:[['Teoría bifactorial; Schachter y Singer',true,'La emoción surge al interpretar cognitivamente la activación fisiológica.'],['Teoría evolutiva; Darwin',false,'Darwin subraya patrones emocionales innatos y adaptativos.'],['Teoría de campo; Lewin',false,'Explica la interacción entre persona y ambiente social.']]},
{id:'q71',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:36,source:'apuntes',prompt:'¿Qué autor defendió que las emociones son patrones innatos, heredados y adaptativos?',options:[['Darwin',true,'El PDF atribuye a Darwin la función evolutiva y programación genética de las emociones.'],['Zajonc',false,'Zajonc propuso una reacción afectiva automática previa al posible procesamiento cognitivo.'],['Lazarus',false,'Lazarus destacó la evaluación cognitiva del estímulo.']]},
{id:'q72',topic:'neuro',kind:'author',modes:['compare','exam'],page:36,source:'apuntes',prompt:'¿Qué autor plantea que el estímulo genera primero una reacción afectiva automática y después puede intervenir el procesamiento cognitivo?',options:[['Zajonc',true,'Esa es la secuencia que los apuntes atribuyen a Zajonc (1982).'],['Lazarus',false,'Lazarus coloca la evaluación cognitiva como determinante de la emoción.'],['James y Lange',false,'Ellos se centran en la percepción de la respuesta fisiológica.']]},
{id:'q73',topic:'neuro',kind:'author',modes:['compare','exam'],page:36,source:'apuntes',prompt:'¿Quién sostiene que la evaluación cognitiva del estímulo determina la emoción resultante?',options:[['Lazarus',true,'El PDF destaca su énfasis en la valoración cognitiva.'],['Cannon y Bard',false,'Proponen simultaneidad entre emoción y respuesta fisiológica.'],['Darwin',false,'Defiende el carácter innato y adaptativo de los patrones emocionales.']]},
{id:'q74',topic:'neuro',kind:'experiment',modes:['learn','apply','exam'],page:37,source:'apuntes',prompt:'Tras el accidente de 1848, Phineas Gage conservó capacidades motoras e intelectuales, pero cambió su personalidad. ¿Qué relación apoyó el caso?',options:[['Lóbulos frontales con emoción, planificación y comportamiento social',true,'Los cambios impulsivos e inapropiados vincularon la lesión frontal con regulación conductual y emocional.'],['Hipocampo con percepción exclusiva del color',false,'No es la estructura ni la función destacada por el caso.'],['Amígdala con el reflejo condicionado de salivación',false,'Confunde el caso neuropsicológico con el condicionamiento clásico.']]},
{id:'q75',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:38,source:'apuntes',prompt:'¿Quién propuso en 1996 la hipótesis del marcador somático?',options:[['Antonio Damasio',true,'El PDF atribuye a Damasio los sentimientos ligados por aprendizaje a resultados futuros previsibles.'],['Joseph LeDoux',false,'Comparte el título del apartado, pero el marcador somático se atribuye a Damasio.'],['Daniel Kahneman',false,'Kahneman aparece en sistemas de procesamiento y decisiones.']]},
{id:'q76',topic:'neuro',kind:'compare',modes:['compare','exam'],page:41,source:'apuntes',prompt:'¿Qué emparejamiento de atención, vía y tiempo es correcto?',options:[['Implícita — camino corto — unos 125 ms; explícita — camino largo — unos 375 ms',true,'La atención automática recibe primero el estímulo y la controlada realiza el análisis deliberado.'],['Implícita — camino largo — 375 ms; explícita — camino corto — 125 ms',false,'Invierte los dos sistemas descritos.'],['Ambas siguen el camino corto y tardan 125 ms',false,'La atención explícita es más lenta y se asocia al camino largo.']]},
{id:'q77',topic:'neuro',kind:'apply',modes:['apply','exam'],page:44,source:'apuntes',prompt:'Se activa el mismo esquema motor al coger una pelota y al observar que otra persona la coge. ¿Qué mecanismo explica el PDF?',options:[['Neuronas espejo',true,'Se activan tanto al ejecutar como al observar la misma acción y apoyan imitación y comprensión.'],['Efecto Forer',false,'Es la aceptación de descripciones vagas como personales.'],['Sistema de aversión a la pérdida',false,'Se activa ante la reducción del nivel habitual de dopamina.']]},
{id:'q78',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:48,source:'apuntes',prompt:'¿Qué hallazgo cromático atribuyen los apuntes a Martin y Foley (1996)?',options:[['El rojo se asocia a una percepción de mayor dulzor',true,'Es la aportación citada literalmente en el bloque de percepción sensorial.'],['El naranja hace que una bebida de cereza se perciba como naranja',false,'Ese resultado se atribuye a Johnson y Clydesdale.'],['Los colores imprevistos hacen parecer insípido un buffet',false,'Esa observación se atribuye a Dubose.']]},
{id:'q79',topic:'neuro',kind:'author',modes:['learn','compare','exam'],page:48,source:'apuntes',prompt:'¿A quién atribuye el PDF que una bebida de cereza coloreada de naranja se perciba como sabor naranja?',options:[['Johnson y Clydesdale (1982)',true,'El color alteró la percepción del sabor con independencia del aroma real.'],['Martin y Foley (1996)',false,'Ellos se asocian a rojo y mayor dulzor percibido.'],['Berlin y Kay',false,'Estudiaron categorías básicas de color entre culturas.']]},
{id:'q80',topic:'neuromarketing',kind:'author',modes:['learn','compare','exam'],page:57,source:'apuntes',prompt:'¿Quién desarrolló el FACS y en qué año según los apuntes?',options:[['Paul Ekman, en 1970',true,'La página 57 atribuye a Ekman el Facial Action Coding System.'],['Féré, en 1881',false,'Féré se relaciona con la respuesta galvánica de la piel.'],['Garry Zaltman, en 2002',false,'Zaltman aparece como impulsor del neuromarketing, no como creador del FACS.']]},
{id:'q81',topic:'neuromarketing',kind:'author',modes:['learn','compare','exam'],page:57,source:'apuntes',prompt:'¿Qué asociación es correcta para la respuesta galvánica de la piel?',options:[['Féré — 1881 — variación de la resistencia o conductancia eléctrica de la piel',true,'Los tres elementos aparecen juntos en el apartado 5.6.'],['Ekman — 1970 — señales BOLD',false,'Ekman desarrolló FACS; BOLD corresponde a fMRI.'],['Pavlov — 1932 — dilatación pupilar',false,'Pavlov estudió reflejos y condicionamiento clásico.']]},
{id:'q82',topic:'neuromarketing',kind:'experiment',modes:['learn','apply','exam'],page:52,source:'apuntes',prompt:'En el estudio Coca-Cola/Pepsi, ¿qué región predecía mejor la elección basada solo en información sensorial?',options:[['Corteza prefrontal ventromedial',true,'Se vincula a valoración sensorial y placer durante la prueba a ciegas.'],['Corteza prefrontal dorsolateral',false,'Aparece, junto al hipocampo y mesencéfalo, cuando se conoce la marca.'],['Lóbulo occipital',false,'No es la región que el PDF señala como mejor predictora de la elección sensorial.']]},
{id:'q83',topic:'neuromarketing',kind:'compare',modes:['compare','exam'],page:53,source:'apuntes',prompt:'¿Qué técnica mide actividad eléctrica cerebral mediante electrodos y bandas delta, theta, alfa, beta y gamma?',options:[['EEG',true,'La electroencefalografía registra la actividad eléctrica del cerebro por bandas de frecuencia.'],['EMG',false,'La electromiografía registra cambios eléctricos de la contracción muscular.'],['ECG',false,'La electrocardiografía registra actividad eléctrica cardíaca.']]},
{id:'q84',topic:'neuromarketing',kind:'apply',modes:['apply','exam'],page:56,source:'apuntes',prompt:'En asimetría frontal, una mayor activación del hemisferio izquierdo se interpreta como…',options:[['Mayor engagement, afecto positivo y aproximación',true,'Los apuntes asocian la activación frontal izquierda con compromiso y acercamiento.'],['Evitación y menor compromiso',false,'Esa interpretación se atribuye a mayor activación del hemisferio derecho.'],['Sueño profundo y ondas delta',false,'Describe un estado de frecuencia cerebral, no la interpretación de asimetría frontal.']]},
{id:'q85',topic:'neuromarketing',kind:'apply',modes:['apply','exam'],page:56,source:'apuntes',prompt:'En un eye tracker, una mayor dilatación pupilar indica principalmente…',options:[['Mayor esfuerzo o nivel de procesamiento cognitivo',true,'El PDF relaciona directamente dilatación pupilar y esfuerzo de procesamiento.'],['Valencia emocional positiva exacta',false,'La pupila no determina por sí sola si la emoción es positiva.'],['Menor tiempo de visionado',false,'El tiempo de visionado se mide aparte y no se deduce así de la dilatación.']]}
];
